+// Sales from the till: each dish sold uses one portion of its recipe per
+// `qty`. A ticket is recorded once; its lines keep the ingredient use they
+// stood for, which is the theoretical use in the variance report.
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** True when a ticket has been recorded. */
+export function hasTicket(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/** Records one ticket line: consumes the ingredients (ref `sale:<ticket>`) and returns the sale. */
+export function sell(store, { ticket, soldAt, dishId, qty }) {
+  const dish = getDish(store, dishId);
+  const use = scaled(getRecipe(store, dish.recipeId), qty).filter((u) => u.qty > 0);
+  for (const u of use) consume(store, u.itemId, u.qty, { at: soldAt, ref: `sale:${ticket}` });
+  store.data.sales ??= [];
+  const sale = { id: store.nextId("sale"), ticket, soldAt, dishId, qty, use };
+  store.data.sales.push(sale);
+  return sale;
+}
